# region Serialization


class SerializationException(Exception):
    """Signal that the JSON serialization could not be performed."""

    #: Human-readable explanation of the exception's cause
    cause: Final[str]

    def __init__(self, cause: str) -> None:
        """Initialize with the given :paramref:`cause` and an empty path."""
        self.cause = cause
        self._segments: List[str] = []

    @property
    def path(self) -> str:
        """
        Render the path to the erroneous value as a Python access expression.

        The path points into the instance which you handed over for
        the serialization, and *not* into a JSON document -- at the point of
        the failure, there is no document yet. For example, ``.submodels[0].value``
        tells you that the serialization broke on ``that.submodels[0].value``.
        """
        return "".join(self._segments)

    def _prepend_property(self, name: str) -> None:
        """Insert the access to the property :paramref:`name` before the path."""
        self._segments.insert(0, f".{name}")

    def _prepend_index(self, index: int) -> None:
        """Insert the access to the item at :paramref:`index` before the path."""
        self._segments.insert(0, f"[{index}]")

    def _prepend_key(self, key: str) -> None:
        """
        Insert the access to the member :paramref:`key` before the path.

        Unlike a property of one of our classes, a member of an open JSON-able
        object is known only at run time and can be any string at all, so it is
        always rendered as a subscript.
        """
        self._segments.insert(0, f"[{json.dumps(key, ensure_ascii=False)}]")

    def __str__(self) -> str:
        if len(self._segments) == 0:
            return self.cause

        return f"{self.path}: {self.cause}"


def _float_to_jsonable(that: float) -> float:
    """
    Serialize :paramref:`that` floating-point number to a JSON-able value.

    JSON knows neither an infinity nor a not-a-number, so we refuse to serialize
    them instead of leaving it to :py:mod:`json` to write them out as ``NaN``
    and ``Infinity``, which no conformant parser reads back.

    :param that: floating-point number to be serialized
    :return: :paramref:`that`, unchanged
    :raise: :py:class:`SerializationException` if not finite
    """
    if not math.isfinite(that):
        raise SerializationException(
            f"JSON knows neither an infinity nor a not-a-number, so the value "
            f"can not be serialized: {that}"
        )
    return that


def _json_value_to_jsonable(value: our_types.JsonValue) -> MutableJsonable:
    """
    Serialize :paramref:`value` as a JSON-able structure.

    A JSON-able value is almost JSON-able as it comes, but not quite: its type
    rules out neither an infinity and a not-a-number, which JSON can not
    represent at all, nor a non-string key in an object. Each is refused here,
    at any depth. A ``None`` is written out as a JSON null.

    The result is a new structure, and never :paramref:`value` itself, so that
    the serialized document does not alias the instance it came from.

    :param value: to be serialized
    :return: :paramref:`value`, as a JSON-able structure
    :raise: :py:class:`SerializationException` if :paramref:`value` is not JSON-able
    """
    if value is None:
        return None

    # NOTE (mristin):
    # A ``bool`` is an ``int`` in Python, so it has to be checked first --
    # otherwise every boolean would come out as a number.
    if isinstance(value, bool):
        return value

    if isinstance(value, int):
        # NOTE (mristin):
        # An ``int`` is written out as it stands. JSON knows a single
        # numeric type, though, so it has to be one which a ``float`` can
        # hold exactly -- otherwise a reader, which reads every number as
        # a ``float``, would get a different number back.
        if our_common.try_to_convert_int_to_float(value) is None:
            raise SerializationException(
                f"Expected a JSON-able value, but got the integer {value}, "
                f"which is not exactly representable as a JSON number"
            )

        return value

    if isinstance(value, float):
        if not math.isfinite(value):
            raise SerializationException(
                f"Expected a JSON-able value, but got the number {value}, "
                f"which is neither finite nor representable in JSON"
            )

        return value

    if isinstance(value, str):
        return value

    if isinstance(value, (dict, collections.abc.Mapping)):
        mapping: Dict[str, Any] = {}
        for key, item_value in value.items():
            if not isinstance(key, str):
                raise SerializationException(
                    f"Expected only string keys in a JSON-able object, but got "
                    f"a key of type: {type(key)}"
                )

            try:
                mapping[key] = _json_value_to_jsonable(item_value)
            except SerializationException as exception:
                exception._prepend_key(key)
                raise

        return mapping

    array_like = our_common.try_to_cast_to_array_like(value)
    if array_like is not None:
        items: List[Any] = []
        for i, item_value in enumerate(array_like):
            try:
                items.append(_json_value_to_jsonable(item_value))
            except SerializationException as exception:
                exception._prepend_index(i)
                raise

        return items

    raise SerializationException(
        f"Expected a JSON-able value (a null, a boolean, a number, a string, "
        f"an array or an object), but got: {type(value)}"
    )


def _bytes_to_base64_str(value: bytes) -> str:
    """
    Encode :paramref:`value` as a base64 string.

    :param value: to be encoded
    :return: encoded :paramref:`value` in base64
    """
    # We need to decode as ascii as ``base64.b64encode`` returns bytes,
    # not a string!
    return base64.b64encode(value).decode("ascii")


